<script setup lang="ts">
import{computed,onMounted,reactive,ref}from"vue";import CpfTreeNode,{type TreeNode}from"../../components/CpfTreeNode.vue";import{bzaApi,hasBzaPermission}from"../auth/session";
type Row=Record<string,any>;const rows=ref<Row[]>([]),selected=ref<TreeNode|null>(null),query=ref(""),error=ref(""),open=ref(false),message=ref("");const form=reactive<Record<string,any>>({});
function build(source:Row[]):TreeNode[]{const by=new Map(source.map(r=>[String(r.menuCode),r]));const child=new Map<string,Row[]>(),roots:Row[]=[];for(const r of source){const p=String(r.parentMenuCode||"");if(!p||!by.has(p))roots.push(r);else{const a=child.get(p)||[];a.push(r);child.set(p,a)}}const walk=(r:Row,path:Set<string>):TreeNode=>{const id=String(r.menuCode);if(path.has(id))return{id,label:String(r.menuName||id),subtitle:id,status:r.useYn,children:[],raw:r,cycle:true};const n=new Set(path);n.add(id);return{id,label:String(r.menuName||id),subtitle:`${id} · ${r.routePath||'NO ROUTE'}`,status:r.useYn,children:(child.get(id)||[]).sort((a,b)=>Number(a.sortOrder||0)-Number(b.sortOrder||0)).map(x=>walk(x,n)),raw:r,orphan:!!r.parentMenuCode&&!by.has(String(r.parentMenuCode))}};return roots.sort((a,b)=>Number(a.sortOrder||0)-Number(b.sortOrder||0)).map(r=>walk(r,new Set()))}
const tree=computed(()=>build(rows.value));const filtered=computed(()=>{const q=query.value.trim().toLowerCase();if(!q)return tree.value;const f=(n:TreeNode):TreeNode|null=>{const c=n.children.map(f).filter(Boolean)as TreeNode[];return(`${n.label} ${n.subtitle}`.toLowerCase().includes(q)||c.length)?{...n,children:c}:null};return tree.value.map(f).filter(Boolean)as TreeNode[]});
async function load(){try{rows.value=await bzaApi('/api/bza/menus')}catch(e){error.value=e instanceof Error?e.message:String(e)}}function edit(node?:TreeNode){const r=node?.raw||{};Object.assign(form,{menuCode:r.menuCode||'',parentMenuCode:r.parentMenuCode||'',menuName:r.menuName||'',routePath:r.routePath||'',sortOrder:r.sortOrder||0,useYn:r.useYn||'Y',reason:'메뉴 Registry 변경'});open.value=true}async function save(){try{await bzaApi('/api/bza/menus',{method:'POST',body:JSON.stringify(form)});open.value=false;await load()}catch(e){message.value=e instanceof Error?e.message:String(e)}}onMounted(load);
</script>
<template><div class="page-stack"><div class="cpf-page-heading"><div><p class="eyebrow">MENU REGISTRY</p><h2>메뉴 Registry</h2><p>Route·상위 메뉴·정렬·상태를 재귀 Tree로 관리합니다.</p></div><button v-if="hasBzaPermission('AUTHORIZATION','WRITE')" class="primary" @click="edit()">메뉴 등록</button></div><p v-if="error" class="error-banner">{{error}}</p><div class="cpf-toolbar"><input v-model="query" placeholder="메뉴명·코드·Route 검색"><span class="count-pill">{{rows.length}} menus</span></div><div class="bza-org-layout"><section class="cpf-card"><div class="cpf-card-body org-tree"><CpfTreeNode v-for="node in filtered" :key="node.id" :node="node" :selected-id="selected?.id" @select="selected=$event"/></div></section><aside class="cpf-card"><div class="cpf-card-head"><h2>메뉴 상세</h2><button v-if="selected&&hasBzaPermission('AUTHORIZATION','WRITE')" class="ghost" @click="edit(selected)">수정</button></div><dl v-if="selected" class="detail-list"><dt>코드</dt><dd>{{selected.raw.menuCode}}</dd><dt>상위</dt><dd>{{selected.raw.parentMenuCode||'ROOT'}}</dd><dt>Route</dt><dd>{{selected.raw.routePath||'-'}}</dd><dt>정렬</dt><dd>{{selected.raw.sortOrder}}</dd><dt>상태</dt><dd>{{selected.raw.useYn}}</dd></dl><div v-else class="cpf-empty">메뉴를 선택하세요.</div></aside></div><dialog :open="open" class="modal"><form class="modal-card" @submit.prevent="save"><div class="card-head"><h2>메뉴 등록·수정</h2><button type="button" class="icon-button" @click="open=false">×</button></div><div class="form-grid"><label><span>메뉴 코드</span><input v-model="form.menuCode" required></label><label><span>상위 메뉴</span><input v-model="form.parentMenuCode"></label><label><span>메뉴명</span><input v-model="form.menuName" required></label><label><span>Route</span><input v-model="form.routePath"></label><label><span>정렬</span><input v-model.number="form.sortOrder" type="number"></label><label><span>사용</span><select v-model="form.useYn"><option>Y</option><option>N</option></select></label><label class="wide"><span>감사 사유</span><textarea v-model="form.reason" required></textarea></label></div><p v-if="message" class="error-banner">{{message}}</p><div class="dialog-actions"><button type="button" class="ghost" @click="open=false">취소</button><button class="primary">저장</button></div></form></dialog></div></template>
